/**
 * Preview of the shop slug generated by the database (public.slugify). Only used to show the
 * future public link while typing: the real slug always comes from create_shop.
 * Ligatures (œ, æ) are not handled like unaccent does; that is acceptable for a preview.
 */
export function slugify(value: string): string {
  const slug = value
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .slice(0, 40)
    .replace(/^-+|-+$/g, "");
  return slug || "boutique";
}
